# Pulumi ComponentResource: WebApp Infrastructure

## Project structure

```
webapp-infra/
├── Pulumi.yaml
├── index.ts
├── component.ts
├── config.ts
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
└── package.json
```

## `config.ts` — typed stack config

```typescript
import * as pulumi from "@pulumi/pulumi";

export interface WebAppConfig {
    environment: "dev" | "prod";
    region: string;
    bucket: {
        replicationRegion?: string; // prod only: cross-region replication
    };
    rds: {
        instanceClass: string;
        multiAz: boolean;
        storageEncrypted: boolean;
        allocatedStorage: number;
    };
    tags: Record<string, string>;
}

export function loadConfig(): WebAppConfig {
    const cfg = new pulumi.Config();
    const env = pulumi.getStack() as "dev" | "prod";

    const dbPassword = cfg.requireSecret("dbPassword"); // encrypted via Pulumi config secret
    return {
        environment: env,
        region: pulumi.getStack() === "prod" ? "us-east-1" : "us-east-2",
        bucket: {
            replicationRegion: env === "prod" ? "us-west-2" : undefined,
        },
        rds: {
            instanceClass: cfg.get("dbInstanceClass") ?? (env === "prod" ? "db.t3.medium" : "db.t3.micro"),
            multiAz: env === "prod",
            storageEncrypted: env === "prod",
            allocatedStorage: cfg.getNumber("dbAllocatedStorage") ?? 20,
        },
        tags: {
            Environment: env,
            ManagedBy: "pulumi",
        },
    };
}
```

## `component.ts` — the ComponentResource

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { WebAppConfig } from "./config";

export interface WebAppComponentArgs {
    config: WebAppConfig;
    dbName: string;
    dbUsername: string;
    dbPassword: pulumi.Output<string>; // secret
}

export class WebAppComponent extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly replicationBucket?: aws.s3.BucketV2;
    public readonly db: aws.rds.Instance;
    public readonly iamRole: aws.iam.Role;
    public readonly dbConnectionString: pulumi.Output<string>;

    constructor(name: string, args: WebAppComponentArgs, opts?: pulumi.ComponentResourceOptions) {
        super("webapp:infra:WebAppComponent", name, args, opts);

        const { config, dbName, dbUsername, dbPassword } = args;
        const isProd = config.environment === "prod";

        // --- S3 bucket: versioned, encrypted, no public access ---
        this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
            tags: config.tags,
        }, { parent: this });

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: this.bucket.bucket,
            versioningConfiguration: { status: "Enabled" },
        }, { parent: this });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-encryption`, {
            bucket: this.bucket.bucket,
            rules: [{
                applySideEncryptionConfiguration: [{
                    sseAlgorithm: isProd ? "aws:kms" : "AES256",
                    ...(isProd ? { kmsMasterKeyID: "alias/aws/s3" } : {}),
                }],
            }],
        }, { parent: this });

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: this.bucket.bucket,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // --- Cross-region replication (prod only) ---
        if (config.bucket.replicationRegion) {
            this.replicationBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {
                tags: config.tags,
            }, {
                parent: this,
                provider: new aws.Provider(`${name}-replica-provider`, {
                    region: config.bucket.replicationRegion,
                }),
            });

            new aws.s3.BucketVersioningV2(`${name}-replica-versioning`, {
                bucket: this.replicationBucket.bucket,
                versioningConfiguration: { status: "Enabled" },
            }, { parent: this });

            const replicaProvider = new aws.Provider(`${name}-replica-role-provider`, {
                region: config.region,
            });

            const replicationRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal({
                    Service: "s3.amazonaws.com",
                }),
            }, { parent: this });

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replicationRole.name,
                policy: this.bucket.arn.apply(bucketArn => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                        Resource: bucketArn,
                    }, {
                        Effect: "Allow",
                        Action: [
                            "s3:GetObjectVersionForReplication",
                            "s3:GetObjectVersionAcl",
                            "s3:GetObjectVersionTagging",
                            "s3:ReplicateObject",
                            "s3:ReplicateDelete",
                            "s3:ReplicateTags",
                        ],
                        Resource: pulumi.interpolate`${bucketArn}/*`,
                    }],
                })),
            }, { parent: this, dependsOn: [replicationRole] });

            new aws.s3.BucketReplicationConfigV2(`${name}-replication-config`, {
                bucket: this.bucket.bucket,
                role: replicationRole.arn,
                rules: [{
                    status: "Enabled",
                    destination: {
                        bucket: this.replicationBucket.arn,
                    },
                }],
            }, { parent: this });
        }

        // --- RDS PostgreSQL ---
        const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: pulumi.output(aws.getSubnetIdsOutput({})).ids, // customize vpcId as needed
        }, { parent: this });

        const dbSecurityGroup = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            description: "RDS access",
            ingress: [{
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
                cidrBlocks: ["10.0.0.0/16"], // internal only
            }],
            egress: [{ protocol: "-1", fromPort: 0, toPort: 0, cidrBlocks: ["0.0.0.0/0"] }],
        }, { parent: this });

        this.db = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: config.rds.instanceClass,
            allocatedStorage: config.rds.allocatedStorage,
            dbSubnetGroupName: dbSubnetGroup.name,
            vpcSecurityGroupIds: [dbSecurityGroup.id],
            dbName,
            username: dbUsername,
            password: dbPassword,
            multiAz: config.rds.multiAz,
            storageEncrypted: config.rds.storageEncrypted || true, // encryption at rest always
            deletionProtection: true,
            publiclyAccessible: false,
            backupRetentionPeriod: 7,
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-final-snapshot`,
        }, { parent: this });

        this.dbConnectionString = pulumi.interpolate`postgresql://${dbUsername}:${dbPassword}@${this.db.endpoint}/${dbName}`;

        // --- IAM role for service accounts (least privilege) ---
        this.iamRole = new aws.iam.Role(`${name}-service-role`, {
            assumeRolePolicy: isProd
                ? JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Federated: `arn:aws:iam::${aws.getCallerIdentityOutput().accountId}:oidc-provider/oidc.eks.${config.region}.amazonaws.com` },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                "oidc.eks.us-east-1.amazonaws.com:sub": `system:serviceaccount:webapp:webapp-sa`,
                            },
                        },
                    }],
                })
                : aws.iam.assumeRolePolicyForPrincipal({ Service: "ec2.amazonaws.com" }),
            tags: config.tags,
        }, { parent: this });

        new aws.iam.RolePolicy(`${name}-service-policy`, {
            role: this.iamRole.name,
            policy: this.bucket.arn.apply(bucketArn => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Action: isProd
                        ? ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
                        : ["s3:*"],
                    Resource: isProd
                        ? [bucketArn, pulumi.interpolate`${bucketArn}/*`]
                        : ["*"],
                }],
            })),
        }, { parent: this });

        this.registerOutputs({
            bucketName: this.bucket.bucket,
            dbEndpoint: this.db.endpoint,
            iamRoleArn: this.iamRole.arn,
        });
    }
}
```

## `index.ts` — stack entrypoint

```typescript
import * as pulumi from "@pulumi/pulumi";
import { WebAppComponent } from "./component";
import { loadConfig } from "./config";

const config = loadConfig();
const cfg = new pulumi.Config();

const app = new WebAppComponent("webapp", {
    config,
    dbName: "webapp",
    dbUsername: cfg.get("dbUsername") ?? "webapp_admin",
    dbPassword: cfg.requireSecret("dbPassword"),
});

export const bucketName = app.bucket.bucket;
export const dbEndpoint = app.db.endpoint;
export const iamRoleArn = app.iamRole.arn;
export const dbConnectionString = app.dbConnectionString; // secret output
```

## `Pulumi.dev.yaml`

```yaml
config:
  webapp-infra:dbUsername: webapp_admin
  webapp-infra:dbPassword:
    secure: AAABANRx4C... # pulumi config set --secret dbPassword
```

## `Pulumi.prod.yaml`

```yaml
config:
  webapp-infra:dbUsername: webapp_admin
  webapp-infra:dbPassword:
    secure: AAABALm2xQ...
  webapp-infra:dbInstanceClass: db.t3.medium
  webapp-infra:dbAllocatedStorage: 50
```

## Deploy

```bash
pulumi stack init dev   && pulumi config set --secret dbPassword '...' && pulumi up
pulumi stack init prod  && pulumi config set --secret dbPassword '...' && pulumi up
```

## Acceptance criteria mapping

| Criterion | Where |
|---|---|
| Bucket versioned + encrypted, no public access | `BucketVersioningV2`, `BucketServerSideEncryptionConfigurationV2` (KMS on prod), `BucketPublicAccessBlock` |
| RDS deletion protection, 7-day backups, not public | `deletionProtection: true`, `backupRetentionPeriod: 7`, `publiclyAccessible: false` |
| Secret never in plaintext | `pulumi config set --secret`, `requireSecret`, secret `Output` for connection string |
| IAM least privilege | prod: OIDC trust + scoped actions; wildcard actions only permitted on dev |
| Cross-region replication (prod) | `BucketReplicationConfigV2` → us-west-2 replica |
| Env isolation | Separate stacks `dev`/`prod` with independent state and configs |
